import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.DGk0zlJw.js";const u=JSON.parse('{"title":"Beacon 组件化重构 · 状态流与组件契约冻结（Phase 0 收口交付）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/design/redesign-2026-10-16-契约.md","filePath":"zh/design/redesign-2026-10-16-契约.md"}'),n={name:"zh/design/redesign-2026-10-16-契约.md"};function i(r,e,a,s,l,g){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="beacon-组件化重构-·-状态流与组件契约冻结-phase-0-收口交付" tabindex="-1">Beacon 组件化重构 · 状态流与组件契约冻结（Phase 0 收口交付） <a class="header-anchor" href="#beacon-组件化重构-·-状态流与组件契约冻结-phase-0-收口交付" aria-label="Permalink to &quot;Beacon 组件化重构 · 状态流与组件契约冻结（Phase 0 收口交付）&quot;">​</a></h1><p><strong>依据</strong>：<code>docs/design/redesign-plan-2026-10-16.md</code>（外部设计稿）+ <code>docs/design/redesign-2026-10-16-核验.md</code>（50 条现状核验，<code>759742b</code>）+ <code>docs/design/redesign-2026-10-16-映射与迁移.md</code>（§6 待拍板清单，<code>e1229fc</code>）。 <strong>时点</strong>：2026-10-16，PATROL1016 巡检单授权「可自主决策的直接拍板并写进仓内决策记录」——本文件即该决策记录；不可逆或超范围事项仍留问（见 §4）。 <strong>性质</strong>：状态流契约与组件契约自此冻结；后续期次（Phase 2-6）在不动本契约公共面的前提下施工，改动契约须新开决策条目。</p><hr><h2 id="_1-四类概念-state-event-command-operation-result" tabindex="-1">1. 四类概念（State / Event / Command / Operation Result） <a class="header-anchor" href="#_1-四类概念-state-event-command-operation-result" aria-label="Permalink to &quot;1. 四类概念（State / Event / Command / Operation Result）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>仓内落点</th><th>语义</th></tr></thead><tbody><tr><td><strong>State</strong></td><td><code>WidgetState</code>（12 字段定性见映射与迁移 §2.1）+ <code>IStateStore</code>（快照面）</td><td>外部系统事实的标准化投影 + 派生态（IsStale/ConnectionHealthy）；唯一权威快照在 State Store</td></tr><tr><td><strong>Event</strong></td><td><code>Events/Events.cs</code> 六记录：<code>WidgetStateChanged</code> <code>ConnectionHealthChanged</code> <code>WidgetsInvalidated</code> <code>AggregateStatusChanged</code> <code>NotificationRaised</code> <code>ActionExecuted</code></td><td>状态流传输面；订阅与取消订阅沿 <code>IEventBus.Subscribe/Publish</code>（UI 侧经 <code>SubscribeOnUi</code> marshal 回 UI 线程，RFC §11）</td></tr><tr><td><strong>Command</strong></td><td><code>ActionConfig.Type</code>（7 个 Type 字符串）→ <code>ActionRunner</code> → <code>IActionExecutor</code></td><td>用户意图的单一入口；执行后定向刷新走 <code>RefreshScheduler.Kick</code>（Action 后状态回灌），不另设命令总线</td></tr><tr><td><strong>Operation Result</strong></td><td><code>ActionResult(ActionId, Success, Message, OutputPath, CompletedAt)</code>（<code>Models/ActionModels.cs:28</code>）</td><td>现行两态（bool Success）；目标五态见 §4 已代决③</td></tr></tbody></table><h2 id="_2-状态流契约-冻结" tabindex="-1">2. 状态流契约（冻结） <a class="header-anchor" href="#_2-状态流契约-冻结" aria-label="Permalink to &quot;2. 状态流契约（冻结）&quot;">​</a></h2><ol><li><strong>发布点</strong>：<code>WidgetHost</code> 成功路径与陈旧路径统一经 <code>IStateStore.Update</code> 发布（<code>f5d1d91</code> 起）；<code>WidgetStateChanged</code> 事件形状不变，UI 无感。</li><li><strong>IStateStore 签名</strong>（<code>Abstractions/IStateStore.cs</code>，<code>f5d1d91</code> 落地即冻结）：<code>Update(WidgetState)</code> / <code>Get(widgetId)</code> / <code>Snapshot()</code> / <code>Invalidate(widgetIds)</code>。</li><li><strong>变更检测口径</strong>（<code>Services/StateStore.cs</code> 内容键）：除 <code>FetchedAt</code> 外全字段参与（长度前缀段防分隔符歧义；Payload 按键排序、插入顺序无关）；<code>IsStale</code> / <code>ConnectionHealthy</code> 翻转必发布（场景 F5：断网降级事件不得被去重吞掉，<code>StateStoreTests.DedupOn_StaleFlip_Republishes</code> 锚定）。</li><li><strong>去重默认启用</strong>（<code>d71bdc8</code>，已代决②）：仅刷新时间变化不触发下游；快照仍保最新 <code>FetchedAt</code>。</li><li><strong>失效</strong>：<code>WidgetsInvalidated</code> 消费方负责丢弃本地残留；<code>Invalidate</code> 为 Store 侧对应清理面（App 侧共享 Store 接线归 Phase 3 绑定引擎一并做，现状 UI 走事件总线不受影响）。</li></ol><h2 id="_3-组件契约-冻结-兼容方案四条照映射与迁移-§5-采纳" tabindex="-1">3. 组件契约（冻结，兼容方案四条照映射与迁移 §5 采纳） <a class="header-anchor" href="#_3-组件契约-冻结-兼容方案四条照映射与迁移-§5-采纳" aria-label="Permalink to &quot;3. 组件契约（冻结，兼容方案四条照映射与迁移 §5 采纳）&quot;">​</a></h2><ol><li>六个 JSON 文件名与既有字段语义不变（config / connections / widgets / pins / actions / notifications）。</li><li>新组件模型以 <code>WidgetConfig</code> 增量可选字段进入，旧文件可读；不迁移、不重命名。<code>ConfigVersion</code> 仅在需要 迁移语义时递增——纯增量可选字段不落键故不动（⑤⑧⑨ 均有单测锚定），存量配置零噪声。</li><li>既有 23 个 Widget 类型键、7 个 Action Type 字符串、全部窗口层级（L0-L3 + Settings）保留；组件化只替换渲染段与状态入口。</li><li>装机 71 条清单与 CI 视觉取证场景继续有效，Phase 6 全量回归后才算期次完成。</li><li>组件描述符形状与挂载面（已代决⑤，<code>src/Beacon.Core/Models/ComponentDescriptor.cs</code>）： <code>ComponentDescriptor(Id, Type, Props, Children)</code> → <code>WidgetConfig.Components: Dictionary&lt;string, ComponentDescriptor&gt;?</code> （面键开集，现行词汇 tile / row / detail）；嵌套组合允许且带上限（8 层 / 32 子 / 256 节点）； 结构非法 = 整树弃用回传统渲染 + 诊断，不静默裁剪。</li><li>绑定与实例（已代决⑥，<code>src/Beacon.Core/Models/ComponentBinding.cs</code> + <code>Services/WidgetInstanceResolver.cs</code>）： 绑定随节点进树（<code>ComponentBinding(Field, Source)</code>），源三态 state / selector / const； 实例 = 面键解析结果，fail-closed（无面树/非法树 → null → 传统渲染）；实例与配置只读共享、解析无 IO。</li><li>绑定引擎（已代决⑦，<code>src/Beacon.Core/Services/ComponentBindingEngine.cs</code>）：树内每个绑定节点的 Field 值按 <code>{节点路径}.{字段}</code> 键出（路径与校验诊断同口径）；源名映射保留键 <code>&quot;&quot;</code> = 自身状态； 一切取不到值的绑定回空串（fail-closed），不抛、不猜；选择器源只接 Core 既有纯函数选择器。</li><li>数据源聚合（已代决⑧，<code>WidgetConfig.Sources: Dictionary&lt;string, Dictionary&lt;string,string&gt;&gt;?</code> 面键 → 源名 → widgetId）：源名大小写敏感精确匹配、不得使用保留键 <code>&quot;&quot;</code>（实例自身状态）、 每面 ≤16 源；声明非法整面弃用（附加源全丢，自身状态恒可用）+ 诊断进加载日志； 运行时源映射由 <code>WidgetInstanceResolver.ResolveSources</code> 从状态快照按 widgetId 查取构建， 查不到的源缺席（绑定侧回空串）；组合在组件层聚合多个 WidgetId，<code>WidgetState</code> 单 <code>ConnectionId</code> 的 Provider 口径不动。</li><li>共享消费（已代决⑨，<code>src/Beacon.Core/Services/ComponentSourceIndex.cs</code>）：同一份状态对象可供任意多个 实例消费（解析纯函数、按引用共享不复制）；<code>ConsumedWidgetIds(instance)</code> 给出实例所需 widgetId 全集 （自身 Id 在前、附加源按声明顺序、同 widgetId 去重），<code>SourcesOf(instances)</code> 反查 widgetId → 消费 实例集合；索引按需重建、不落缓存。</li><li>组件层纯函数边界（已代决⑩）：<code>ComponentTreeValidator</code> / <code>ComponentSourcesValidator</code> / <code>WidgetInstanceResolver</code> / <code>ComponentBindingEngine</code> / <code>ComponentSourceIndex</code> 全为静态类（无实例状态、 无缓存面），任何公共方法都不接收运行时服务（Provider / 执行器 / Store / 事件总线 / Clock 等）—— 状态与配置只作为数据参数传入；状态查取次数只由源声明决定、与布局形状无关，引擎解析期零查取。 改布局 = 对同一份状态快照重新解析，不产生数据请求（Phase 3 行 6 的构造与测试双锚定）。</li></ol><h2 id="_4-决策记录" tabindex="-1">4. 决策记录 <a class="header-anchor" href="#_4-决策记录" aria-label="Permalink to &quot;4. 决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>决定</th><th>依据与回退</th><th>状态</th></tr></thead><tbody><tr><td>已代决①</td><td><code>IStateStore</code> 契约冻结 = <code>f5d1d91</code> 落地签名</td><td>已落地 + 15 项单测；单 commit 可回退</td><td>生效</td></tr><tr><td>已代决②</td><td><code>FetchedAt</code> 移出内容相等，<code>suppressUnchanged</code> 默认 true（<code>d71bdc8</code>）</td><td>设计稿 §4.1 明示；stale/健康翻转必发有单测锚定；Last update 仅陈旧态显示（RFC §6.2.6），新鲜态去重无可见时间戳损失；回退开关保留（构造参数传 false），单 commit 回滚</td><td>生效</td></tr><tr><td>已代决③</td><td><code>ActionResult</code> 目标五态（Succeeded / Failed / Cancelled / TimedOut / Unsupported，另区分「请求已接受」与「最终完成」），Phase 5 反馈系统落地时演进，现行两态兼容保留</td><td>五态是契约演进非破坏：新成员增量进入，执行器逐个映射；提前改会空转（现无 Cancel/Timeout 执行面）</td><td>已定待施（Phase 5）</td></tr><tr><td>已代决④</td><td>映射与迁移 §5 兼容方案四条照此冻结（本文件 §3）</td><td>全部为保守不变面；变更须新开决策条目</td><td>生效</td></tr><tr><td>已代决⑤</td><td>组件描述符形状：<code>ComponentDescriptor(Id?, Type, Props:string→string, Children[])</code> 挂 <code>WidgetConfig.Components: Dictionary&lt;string,ComponentDescriptor&gt;?</code>（面键开集，现行 tile/row/detail）；<strong>嵌套组合允许</strong>，防爆上限 8 层/32 子/256 节点；结构非法整树弃用回传统渲染+诊断</td><td>用户 2026-10-16 授权代决描述符形状（FW1016D）。§3.2 已框定「增量可选字段」，本条只定形状：① 面键开集而非单根——同一 widget 在 L0 tile / L2 行 / L3 详情三形态各异，单根树会强迫三层同形；② Props 全字符串——与 <code>WidgetConfig.Config</code>/<code>ActionConfig.Parameters</code> 同口径，JSON 手写不出类型歧义，类型换算留渲染期；③ 允许嵌套是描述符的存在理由（Surface.Card 包 Text、StatusCard 包指示灯+标题，as-built §2 已按此组合），但无限嵌套会让一处手误放大成递归爆栈——故带上限且非法整树弃用（不静默裁剪成半棵、不崩常驻进程）；④ 组件类型键的注册表与未知键策略留 Phase 3 行 3 绑定分发（注册表在渲染侧，此处不预设）；⑤ 无迁移语义故 <code>ConfigVersion</code> 不动（可选字段不落键，存量 widgets.json 零噪声可读，有单测锚定）</td><td>生效</td></tr><tr><td>已代决⑥</td><td>绑定声明随节点进树（<code>ComponentBinding(Field, Source)</code> 挂 <code>ComponentDescriptor.Bindings</code>）；绑定源三态 <code>state</code>/<code>selector</code>/<code>const</code>（state 路径受支持字段集封闭 + <code>payload:key</code>）；附加数据源走 <code>SourceName</code>（映射见 ⑧）；实例解析 fail-closed（无面树/非法树 → null → 传统渲染），实例与配置按只读共享</td><td>用户 2026-10-16 授权代决描述符形状（FW1016D），本条是描述符的绑定面。① 随节点进树而非 widget 级绑定表——绑定表要再带节点定位符，等于把树描述两遍；② 三态源覆盖全部取值场景（自身状态字段 / 派生选择器 / 静态字面），自由路径 DSL 会让手写 JSON 的出错面无界；③ 校验前移到加载与解析期，运行期不猜坏路径（未知 kind、坏路径在解析时即报错，进诊断日志）；④ 实例不复制树与 Config，按只读共享（同 <code>WidgetConfig.Config</code> 字典口径），改布局只重解析、无 IO</td><td>生效</td></tr><tr><td>已代决⑦</td><td>绑定引擎 = 纯函数 <code>ComponentBindingEngine.Resolve(WidgetInstance, WidgetState)</code> / <code>Resolve(WidgetInstance, IReadOnlyDictionary&lt;string,WidgetState&gt;)</code>；树内绑定值按 <code>{节点路径}.{字段}</code> 键出；源名映射保留键 <code>&quot;&quot;</code> = 自身状态（主状态），附加源名由 ⑧ 的实例数据源声明构建；取不到值一律空串；选择器源注册表只收 Core 既有纯函数（<code>value-hint</code> = <code>WidgetValueHint.Of</code>，<code>quota-windows</code> = <code>WidgetValueHint.MultiWindow</code>）</td><td>用户 2026-10-16 授权代决（FW1016D），本条是描述符绑定面的运行期执行器。① 纯函数、无 IO、无 Provider 依赖是 Phase 3 行 6 不变量的构造保证——状态由调用面以快照传入，改布局只重解析不触发请求；② 路径键与校验诊断同一口径（id 或 <code>child{index}</code>，<code>/</code> 连接），渲染段与诊断日志能互指同一个节点，不再第二套定位符；③ 取不到值回空串而非抛——常驻进程里一个手写 JSON 的错值不能炸整个面板，缺值表现为空串（行 3 校验已在加载/解析期把坏路径报错进诊断，运行期只做兜底）；④ 选择器注册表不收用户可写项——新选择器走 Core 代码加注册表条目，避免 JSON 里出现任意 callable 面</td><td>生效</td></tr><tr><td>已代决⑧</td><td>多数据源组合：面级声明 <code>WidgetConfig.Sources</code>（面键 → 源名 → widgetId）增量可选字段；运行时映射由 <code>WidgetInstanceResolver.ResolveSources(instance, stateOf)</code> 从状态快照按 widgetId 查取构建（查不到的源缺席，绑定侧回空串）；源名大小写敏感精确匹配；保留键 <code>&quot;&quot;</code> = 实例自身状态且附加声明不得使用；每面 ≤16 源；声明非法整面弃用（附加源全丢、自身状态恒可用）+ 诊断进加载日志</td><td>用户 2026-10-16 授权代决（FW1016D）。映射与迁移 §3.3 已框定「组合发生在组件层聚合多个 WidgetId，<code>WidgetState</code> 单 <code>ConnectionId</code> 的 Provider 口径不破坏」，本条落实现面：① 声明挂面级而非节点级——数据源聚合是实例属性，与 <code>Components</code> 同级同一面键口径，不在树节点上再挂一份（节点只写 <code>SourceName</code> 引用）；② 保留键 <code>&quot;&quot;</code> 承载自身状态、附加源显式命名——实例 Id 已是自身，按 widgetId 直接寻址会重复且 JSON 里不可读（&quot;runs&quot;/&quot;quota&quot; 比 widgetId 好写）；③ 源名精确匹配不忽略大小写——源名是用户写死的标识符，静默容错大小写比报错更难排查；④ 声明非法只弃该面附加源、不弃实例：附加源是增量能力，自身状态恒可用，因一条坏声明把整个面打回传统渲染是超额惩罚（组件树的结构非法才整树弃用——树是渲染骨架，源不是）；⑤ 每面 16 源上限与 Components 的 8/32/256 同属手写 JSON 防爆半径；⑥ 不随 <code>ConfigVersion</code> 动（可选字段不落键，存量 widgets.json 零迁移可读，有单测锚定）</td><td>生效</td></tr><tr><td>已代决⑨</td><td>不同组件共享同一份状态：解析纯函数只读状态、按引用共享不复制；<code>ComponentSourceIndex.ConsumedWidgetIds(instance)</code> = 实例所需 widgetId 全集（自身 Id 在前、附加源按声明顺序、同 widgetId 去重），<code>ComponentSourceIndex.SourcesOf(instances)</code> 反查 widgetId → 消费实例集合；索引纯函数、按需重建、不落缓存</td><td>用户 2026-10-16 授权代决（FW1016D）。设计稿验收 3「同一份数据可以被不同类型的组件展示」+ 验收 7「数据变化只更新必要的消费者」，本条落可反查的事实面：① 按引用共享而非克隆——一份状态被 N 个面消费时内存里只有一份，<code>WidgetState</code> 的内容相等（去重/事件口径）在共享时才有意义；② 索引双向都要——「这份状态被谁消费」是失效与更新的路由面（行 6），「这个组件要哪些源」是订阅与刷新的范围面（⑧ 的源声明），两者从同一份 Sources 声明推导，不会出现两套口径；③ 自身 Id 恒入消费集合——绑定 SourceName 为空时读的就是自身状态，漏登记会把「这份状态变了」漏掉自己这个消费者；④ 索引不缓存——缓存放哪、何时失效正是「无意义请求」的来源（行 6 正面处理的对象）</td><td>生效</td></tr><tr><td>已代决⑩</td><td>组件层纯函数边界（Phase 3 行 6）：组件层五个类型（<code>ComponentTreeValidator</code> / <code>ComponentSourcesValidator</code> / <code>WidgetInstanceResolver</code> / <code>ComponentBindingEngine</code> / <code>ComponentSourceIndex</code>）全为静态类，任何公共方法都不接收运行时服务（<code>IConnectionProvider</code> / <code>IActionExecutor</code> / <code>IStateStore</code> / <code>IConfigurationStore</code> / <code>ICacheStore</code> / <code>ISecretStore</code> / <code>IEventBus</code> / <code>IClock</code> / <code>INotificationSink</code>）；状态查取次数 = 自身 1 次 + Sources 声明数，与布局形状无关；引擎拿到映射后零查取</td><td>用户 2026-10-16 授权代决（FW1016D）。行 6 是「保证」不是「功能」，本条把它变成可回归的边界：① 反射守公共签名——一旦有人为「顺手取数」把 Provider 或 Store 塞进组件层，改布局就会顺带发起数据请求，测试直接红，比评审和注释更早发现；② 查取计数守行为——布局从 1 个节点到 200 层嵌套，状态查取次数不变（2 次 = 自身 + 1 个附加源），引擎解析期零查取，直接证明「布局不驱动数据请求」；③ 静态类 = 没有缓存面，也就不存在「什么时候失效」的问题——⑨ 已定索引按需重建不落缓存，本条把这条约束泛化到整个组件层（缓存放哪、何时失效正是「无意义请求」的来源）</td><td>生效</td></tr><tr><td><strong>留问</strong></td><td>HTML 小屏幕与 <code>master-plan.md:769</code>「不引入 WebView」的边界（映射与迁移 §6.3）</td><td><strong>已裁定（2026-10-17 用户令「这个设计下吧」）</strong>：受控 HTML/CSS 子集 + 原生渲染、无 JS 无 WebView2（决策全文：docs/design/phase4-html-ruling-2026-10-17.md）</td><td>已关闭</td></tr></tbody></table><h2 id="_5-未尽事项" tabindex="-1">5. 未尽事项 <a class="header-anchor" href="#_5-未尽事项" aria-label="Permalink to &quot;5. 未尽事项&quot;">​</a></h2><ul><li><code>BeaconRuntime</code> 创建共享 <code>StateStore</code> 并注入 <code>WidgetHost</code>/未来绑定引擎（App 侧接线，Phase 3）；现状 <code>WidgetHost</code> 内部默认 Store 即生效。</li><li><code>Events.cs</code> 事件计数：映射与迁移 §1.6 原记「5 个事件记录」实为 6（含 <code>ActionExecuted</code>），已随本文件更正。</li></ul><h2 id="_6-能力边界三层标注-p0-01-2026-10-17" tabindex="-1">6. 能力边界三层标注（P0-01，2026-10-17） <a class="header-anchor" href="#_6-能力边界三层标注-p0-01-2026-10-17" aria-label="Permalink to &quot;6. 能力边界三层标注（P0-01，2026-10-17）&quot;">​</a></h2><p>组件契约描述「可写什么」；实际支持程度分三层，各面（<code>tile</code> / <code>row</code> / <code>detail</code>）口径如下—— 别把「契约允许」当「已验收」，验收以装机清单为准（§3.4 的 71 条与 Phase 6 全量回归）：</p><table tabindex="0"><thead><tr><th>层</th><th>范围</th><th>tile</th><th>row</th><th>detail</th></tr></thead><tbody><tr><td>Core 模型可用</td><td><code>ComponentDescriptor</code> / 树校验 / 源校验 / <code>WidgetInstanceResolver</code> / <code>ComponentBindingEngine</code> / <code>ComponentSourceIndex</code>（静态纯函数，Core 单测锚定）</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>App 已接线</td><td>声明式渲染 + 绑定取值 + 附加源路由（PinTile / FloatingTile / QuickPanel 行 / DetailWindow）+ 缺源显示</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>真实用户场景已验收</td><td>装机 71 条清单 + Phase 6 回归 + 样例运行时验收（<code>docs/samples/declarative-vertical-sample.md</code>「验什么」）</td><td>⏳</td><td>⏳</td><td>⏳</td></tr></tbody></table><p>口径注记：保存组件树只落盘 + 重排注册（P3-02 分流），不取数、不发布重渲事件—— 面随<strong>下一次状态到达</strong>按新树渲染；状态内容无变化被去重压住时，重开对应面可见。 设置页保存反馈文案与此对齐，不声称「正在重渲染」。</p>',17)])])}const S=t(n,[["render",i]]);export{u as __pageData,S as default};
